from collections import defaultdict

class Solution:
    def countPoints(self, rings: str) -> int:
        rods = defaultdict(set)
        for i in range(0, len(rings), 2):
            rods[rings[i + 1]].add(rings[i])
        return sum(len(s) == 3 for s in rods.values())

