class Solution {
public:
    int countPoints(string rings) {
        unordered_map<char, unordered_set<char>> rods;
        for (int i = 0; i < (int)rings.size(); i += 2)
            rods[rings[i + 1]].insert(rings[i]);
        int ans = 0;
        for (auto& [rod, colors] : rods)
            if (colors.size() == 3) ++ans;
        return ans;
    }
};

