class Solution {
    public int countPoints(String rings) {
        Map<Character, Set<Character>> rods = new HashMap<>();
        for (int i = 0; i < rings.length(); i += 2)
            rods.computeIfAbsent(rings.charAt(i + 1), k -> new HashSet<>()).add(rings.charAt(i));
        int ans = 0;
        for (Set<Character> s : rods.values())
            if (s.size() == 3) ++ans;
        return ans;
    }
}

