var countPoints = function(rings) {
    const rods = new Map();
    for (let i = 0; i < rings.length; i += 2) {
        const rod = rings[i + 1];
        if (!rods.has(rod)) rods.set(rod, new Set());
        rods.get(rod).add(rings[i]);
    }
    let ans = 0;
    for (const s of rods.values()) if (s.size === 3) ++ans;
    return ans;
};

